insert into public.services (name, category, price, active)
values
  ('Micropigmentación', 'Micropigmentación', 0, true),
  ('Botox - Ácido hialurónico', 'Inyectables', 0, true),
  ('Novias', 'Maquillaje y peinado', 0, true),
