  ('Seminarios', 'Formación', 0, true),
  ('Cursos de automaquillaje', 'Formación', 0, true),
  ('It Works', 'Bienestar', 0, true),
  ('Curso de maquillaje profesional', 'Formación', 0, true)
on conflict ((lower(name))) do update
set category = excluded.category,
    active = true,
    updated_at = now();

