  normalized_phone text;
  alternate_note text;
begin
  for customer_record in
    select value from jsonb_array_elements(import_data)
  loop
    normalized_phone := regexp_replace(
      coalesce(customer_record->>'whatsapp', customer_record->>'phone', ''),
      '\D',
      '',
      'g'
    );

    select customer.id
      into target_customer_id
    from crm_import_existing_customers customer
    where (
      nullif(customer_record->>'email', '') is not null
      and lower(trim(customer.email)) = lower(trim(customer_record->>'email'))
    )
    or (
      normalized_phone <> ''
      and regexp_replace(coalesce(customer.whatsapp, customer.phone, ''), '\D', '', 'g') = normalized_phone
    )
    order by
      case
        when nullif(customer_record->>'email', '') is not null
          and lower(trim(customer.email)) = lower(trim(customer_record->>'email')) then 0
        else 1
      end,
      customer.created_at
    limit 1;

    if target_customer_id is null then
      select customer.id
        into target_customer_id
      from crm_import_existing_customers customer
      where lower(trim(customer.full_name)) = lower(trim(customer_record->>'full_name'))
      order by customer.created_at
      limit 1;
    end if;

    alternate_note := concat_ws(
      E'\n',
      case
        when jsonb_array_length(customer_record->'alternate_phones') > 0
        then 'Teléfonos alternos importados: ' || (
          select string_agg(value, ', ')
          from jsonb_array_elements_text(customer_record->'alternate_phones')
        )
      end,
      case
        when jsonb_array_length(customer_record->'alternate_emails') > 0
        then 'Correos alternos importados: ' || (
          select string_agg(value, ', ')
          from jsonb_array_elements_text(customer_record->'alternate_emails')
        )
      end
    );

    if target_customer_id is null then
      insert into public.customers (
        full_name,
        company,
        email,
        phone,
        whatsapp,
        status,
        owner,
        owner_name,
        preferred_contact_channel,
        notes
      )
      values (
        customer_record->>'full_name',
        'Particular',
        nullif(customer_record->>'email', ''),
        nullif(customer_record->>'phone', ''),
        coalesce(nullif(customer_record->>'whatsapp', ''), ''),
        'activo',
        'Importación Excel',
        'Importación Excel',
        customer_record->>'preferred_contact_channel',
        nullif(alternate_note, '')
      )
      returning id into target_customer_id;
    else
      update public.customers
      set email = coalesce(nullif(email, ''), nullif(customer_record->>'email', '')),
          phone = coalesce(nullif(phone, ''), nullif(customer_record->>'phone', '')),
          whatsapp = coalesce(nullif(whatsapp, ''), nullif(customer_record->>'whatsapp', '')),
          preferred_contact_channel = case
            when nullif(email, '') is not null then coalesce(preferred_contact_channel, 'email')
            when nullif(customer_record->>'email', '') is not null then 'email'
            else coalesce(preferred_contact_channel, 'whatsapp')
          end,
          notes = concat_ws(E'\n', nullif(notes, ''), nullif(alternate_note, '')),
          updated_at = now()
      where id = target_customer_id;
    end if;

    for history_record in
      select value from jsonb_array_elements(customer_record->'histories')
    loop
      select service.id
        into target_service_id
      from public.services service
      where lower(service.name) = lower(history_record->>'service_name')
      limit 1;

      insert into public.customer_service_history (
        customer_id,
        service_id,
        service_name,
        payment_status,
        source_type,
        source_reference,
        import_key
      )
      values (
        target_customer_id,
        target_service_id,
        history_record->>'service_name',
        'sin_registro',
        'importacion',
        (history_record->>'source_sheet') || ' - fila ' || (history_record->>'source_row'),
        'expedientes-20260723:' || target_customer_id || ':' || md5(lower(history_record->>'service_name'))
      )
      on conflict (import_key) do nothing;
    end loop;
  end loop;
end
$$;
